import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Determine plane size based on source rect aspect (default 512x320)
  const src = config.atlasRegion?.sourceRect ?? { width: 512, height: 320 };
  const aspect = src.width / src.height;
  const planeWidth = aspect; // 1 unit height, width = aspect
  const planeHeight = 1;

  // Geometry and material
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives for this node, but keep API compatibility
  const primitiveInstances = [];

  // Attach cleanup
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose material and geometry
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();

    // Cleanup any primitive resources
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });
  };

  return root;
}
